   118	var lookupWhyCheckpointInfo = func(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
   119		if repo == nil {
   120			var err error
   121			repo, err = openRepository(ctx)
   122			if err != nil {
   123				return nil, err
   124			}
   125		}
   126	
   127		v1Store := checkpoint.NewGitStore(repo)
   128		v2Store := checkpoint.NewV2GitStore(repo, "origin")
   129	
   130		reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpointID, v1Store, v2Store, true)
   131		if err != nil {
   132			return nil, err
   133		}
   134	
   135		return loadWhyEntireInfo(ctx, reader, summary, checkpointID, commitSubject)
   136	}
   137	
   138	var loadWhyEntireInfo = loadWhyEntireInfoImpl
   139	
   140	func loadWhyEntireInfoImpl(ctx context.Context, reader checkpoint.CommittedReader, summary *checkpoint.CheckpointSummary, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
   141		if summary == nil {
   142			return nil, nil
   143		}
   144	
   145		sessionIndex := len(summary.Sessions) - 1
   146		if sessionIndex < 0 {
   147			return &whyEntireInfo{
   148				CheckpointID: checkpointID.String(),
   149				Summary:      commitSubject,
   150				IsFallback:   true,
   151			}, nil
   152		}
   153	
   154		sessionMetadata, err := readWhySessionMetadata(ctx, reader, checkpointID, sessionIndex)
   155		if err != nil {
   156			return nil, err
   157		}
   158		if sessionMetadata == nil {
   159			return &whyEntireInfo{
   160				CheckpointID: checkpointID.String(),
   161				Summary:      commitSubject,
   162				IsFallback:   true,
   163			}, nil
   164		}
   165	
   166		summaryText, isFallback := selectWhySummary(sessionMetadata.Summary, commitSubject)
   167		return &whyEntireInfo{
   168			CheckpointID: checkpointID.String(),
   169			Agent:        string(sessionMetadata.Agent),
   170			Summary:      summaryText,
   171			IsFallback:   isFallback,
   172		}, nil
   173	}
   174	
   175	var readWhySessionMetadata = func(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error) {
   176		if err := ctx.Err(); err != nil {
   177			return nil, err
   178		}
   179	
   180		switch r := reader.(type) {
   181		case interface {
   182			ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error)
   183		}:
   184			return r.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
   185		case interface {
   186			ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error)
   187		}:
   188			content, err := r.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
   189			if err != nil {
   190				return nil, err
   191			}
   192			if content == nil {
   193				return nil, nil
   194			}
   195			return &content.Metadata, nil
   196		default:
   197			return nil, fmt.Errorf("reader does not support metadata-only session reads")
   198		}
   199	}
   200	
   201	func selectWhySummary(summary *checkpoint.Summary, commitSubject string) (string, bool) {
   202		if summary != nil {
   203			if text := strings.TrimSpace(summary.Outcome); text != "" {
   204				return text, false
   205			}
   206			if text := strings.TrimSpace(summary.Intent); text != "" {
   207				return text, true
   208			}
   209		}
   210	
   211		if text := strings.TrimSpace(commitSubject); text != "" {
   212			return text, true
   213		}
   214	
   215		return "", true
   216	}
